from jsonb_to_recordset($curriculum$[{"phase": "attack", "level": "individual", "component": "Ігрове положення", "title": "Навчити знаходити місце, де можна отримати передачу без перешкоди з боку суперника.", "description": "(Вийти з-за суперника; показати партнеру готовність отримати м’яч.)", "age_from": 6, "age_to": 6, "sort_order": 1, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Ігрове положення", "title": "Навчити обирати розташування та орієнтацію корпусу для продовження гри в напрямку воріт суперника.", "description": "(Розрізняти власні ворота й ворота суперника; помічати доступний шлях до цілі.)", "age_from": 6, "age_to": 6, "sort_order": 2, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Зупинка м’яча", "title": "Навчити обирати зупинку м’яча, коли шлях для негайного просування перекритий.", "description": "(Залишати м’яч доступним для наступної дії.)", "age_from": 6, "age_to": 6, "sort_order": 3, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Захист м’яча тілом", "title": "Навчити закривати м’яч тілом під час спроби суперника його відібрати.", "description": "(Зберігати м’яч поруч; не відштовхувати суперника.)", "age_from": 6, "age_to": 6, "sort_order": 4, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Ведення м’яча", "title": "Навчити обирати вільний напрямок для просування з м’ячем.", "description": "(Якщо суперник перекрив шлях — шукати інший доступний напрямок.)", "age_from": 6, "age_to": 6, "sort_order": 5, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Обведення суперника", "title": "Навчити обводити суперника через вільний бік.", "description": "(У грі один проти одного дати вибір