: "(Не втрачати м’яч із поля зору під час переміщення.)", "age_from": 6, "age_to": 6, "sort_order": 12, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Ігрове положення в захисті", "title": "Навчити після втрати м’яча повертатися за лінію м’яча для захисту власних воріт.", "description": "(Якщо негайно повернути м’яч неможливо; зайняти місце ближче до власних воріт, ніж м’яч.)", "age_from": 6, "age_to": 6, "sort_order": 13, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Боротьба за м’яч", "title": "Навчити вступати в боротьбу за вільний м’яч, коли є можливість дістатися до нього раніше за суперника.", "description": "(М’яч на поверхні поля; порівнювати відстань до нього.)", "age_from": 6, "age_to": 6, "sort_order": 14, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Відбирання м’яча", "title": "Навчити обирати спробу відбирання, коли суперник відпустив м’яч від себе.", "description": "(Намагатися зіграти в доступний м’яч.)", "age_from": 6, "age_to": 6, "sort_order": 15, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Індивідуальний пресинг", "title": "Навчити наближатися до суперника з м’ячем, щоб завадити його вільному просуванню.", "description": "(Рухатися до суперника, зберігаючи можливість відреагувати на зміну його напрямку.)", "age_from": 6, "age_to": 6, "sort_order": 16, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Ігрове положення", "title": "Навчити обирати відстань до партнера, з якої можна отримати передачу.", "description": "(Не підбігати впритул; показувати готовність поглядом або голосом.)", "age_from": 7, "age_to": 7, "sort_order": 17, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Зупинка м’яча", "title": "Навчити першим контактом спрямовувати м’яч у вільний бік.", "description": "(До отримання помітити, з якого боку наближається суперник.)", "age_from": 7, "age_to": 7, "sort_order": 18, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Зупинка м’яча", "title": "Навчити першим контактом відводити м’яч від суперника, який наближається.", "description": "(Оцінити бік наближення ще до отримання передачі.)", "age_from": 7, "age_to": 7, "sort_order": 19, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Зупинка м’яча", "title": "Навчити обирати приймання під захист корпусу за близької протидії суперника.", "description": "(Залишити своє тіло між суперником і м’ячем.)", "age_from": 7, "age_to": 7, "sort_order": 20, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Захист м’яча тілом", "title": "Навчити обирати захист м’яча спиною або боком до суперника.", "description": "(Змінювати положення відповідно до боку його наближення.)", "age_from": 7, "age_to": 7, "sort_order": 21, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Ведення м’яча", "title": "Навчити вести м’яч від суперника для збереження володіння.", "description": "(Коли просування до воріт перекрите, помітити вільний простір збоку або позаду.)", "age_from": 7, "age_to": 7, "sort_order": 22, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Обведення суперника", "title": "Навчити обирати стартовий ривок із м’ячем у вільний від суперника напрямок.", "description": "(Використати момент, коли суперник ще не встигає перекрити шлях.)", "age_from": 7, "age_to": 7, 