 "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Боротьба за м’яч", "title": "Навчити перед боротьбою за м’яч займати вигідніше місце відносно суперника.", "description": "(Оцінювати шлях до м’яча й можливий контакт; не поступатися місцем через спостереження лише за м’ячем.)", "age_from": 11, "age_to": 11, "sort_order": 145, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Блокування м’яча", "title": "Навчити обирати блокування передачі, коли оволодіти м’ячем до адресата неможливо.", "description": "(Перервати рух м’яча або змінити напрямок; бути готовим до відскоку.)", "age_from": 11, "age_to": 11, "sort_order": 146, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Індивідуальний пресинг", "title": "Навчити обирати напрямок пресингового зближення спереду, збоку або ззаду.", "description": "(Захищати небезпечне продовження; зближуватися без порушення правил і без сліпого ривка повз м’яч.)", "age_from": 11, "age_to": 11, "sort_order": 147, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Індивідуальний пресинг", "title": "Навчити переносити індивідуальний пресинг на нового суперника з м’ячем після передачі.", "description": "(Порівняти свою відстань із можливістю партнера вийти до адресата; повідомити, хто продовжує зближення.)", "age_from": 11, "age_to": 11, "sort_order": 148, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Розподіл опіки", "title": "Навчити партнерів розподіляти опіку суперників, які входять у їхні зони.", "description": "(Назвати або показати нового суперника; перевірити, що партнер зрозумів зміну розподілу.)", "age_from": 11, "age_to": 11, "sort_order": 149, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Переключення опіки", "title": "Навчити передавати опіку партнеру під час переходу суперника до його зони.", "description": "(Повідомити про передавання; партнер підтверджує прийняття до припинення попередньої опіки.)", "age_from": 11, "age_to": 11, "sort_order": 150, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Підстраховка", "title": "Навчити підстраховувати простір за партнером від передачі й переміщення суперника.", "description": "(Підстраховка можлива позаду, діагонально або збоку; повідомляти партнеру про загрозу за його спиною.)", "age_from": 11, "age_to": 11, "sort_order": 151, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Подвоєння", "title": "Навчити двійку одночасно протидіяти конкретному супернику з м’ячем із двох напрямків.", "description": "(Узгодити момент зближення; не залишати зручного проходу між собою.)", "age_from": 11, "age_to": 11, "sort_order": 152, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Груповий пресинг", "title": "Навчити трійку під час пресингу спрямовувати суперника до бічної лінії.", "description": "(Один зближується, другий закриває центр, третій опікає ближнього адресата; підтвердити готовність до спільного початку.)", "age_from": 11, "age_to": 11, "sort_order": 153, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Організація захисної структури", "title": "Навчити команду розподіляти футболістів між захисними лініями у форматі 8+1.", "description": "(Узгодити початкові місця; повідомляти партнеру, коли потрібно прийняти суперника або закрити звільнену позицію.)", "age_from": 11, "age_to": 11, "sort_order": 154, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Відкривання", "title": "Навчити відкриватися між захисними лініями в момент готовності партнера передати.", "description": "(Помітити, коли партнер звільнив м’яч для передачі; показати потрібний бік отримання.)", "age_from": 12, "age_to": 12, "sort_order": 155, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Відкривання", "title": "Навчити відкриватися за краєм захисного розташування суперника.", "description": "(Показати партнеру доступний обхідний напрямок; не звужувати його під час підготовки передачі.)", "age_from": 12, "age_to": 12, "sort_order": 156, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Передача м’яча", "title": "Навчити передачею з недодачею викликати наближення партнера для отримання м’яча.", "description": "(Узгодити наближення партнера жестом або рухом; він має встигати до м’яча раніше за суперника.)", "age_from": 12, "age_to": 12, "sort_order": 157, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Передача м’яча", "title": "Навчити узгоджувати подачу з виходом партнера в обрану зону.", "description": "(До виконання показати напрямок; адресат підлаштовує ривок під момент подачі.)", "age_from": 12, "age_to": 12, "sort_order": 158, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Передача м’яча", "title": "Навчити скидати м’яч під удар партнеру, який підходить до зони завершення.", "description": "(Партнер повідомляє про підхід; гравець скидки перевіряє його місце до контакту з м’ячем.)", "age_from": 12, "age_to": 12, "sort_order": 159, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Боротьба за перший м’яч", "title": "Навчити узгоджувати спрямування першого м’яча у простір із виходом партнера в цю зону.", "description": "(Партнер показує напрямок; гравець першого контакту перевіряє його готовність до продовження.)", "age_from": 12, "age_to": 12, "sort_order": 160, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Підбирання м’яча", "title": "Навчити після підбирання обирати збереження м’яча, просування або негайне завершення.", "description": "(Оцінювати тиск і ворота; партнери повідомляють про доступну передачу або наближення суперника.)", "age_from": 12, "age_to": 12, "sort_order": 161, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Заслін", "title": "Навчити використовувати дозволену позицію партнера для виграшу часу гравцю з м’ячем.", "description": "(Партнери узгоджують напрямок виходу; заслін не створюють утримуванням або незаконним блокуванням руху.)", "age_from": 12, "age_to": 12, "sort_order": 162, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Заслін", "title": "Навчити заздалегідь займати дозволене місце для полегшення переміщення партнера без м’яча.", "description": "(До руху узгодити напрямок; зайняте місце не дає права незаконно перешкоджати супернику.)", "age_from": 12, "age_to": 12, "sort_order": 163, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Комбінації", "title": "Навчити пропускати м’яч партнеру, який має краще продовження нападу.", "description": "(До пропускання почути його або перевірити розташування; партнер повідомляє про готовність.)", "age_from": 12, "age_to": 12, "sort_order": 164, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Позиційна підтримка атаки", "title": "Навчити одному з партнерів зберігати підтримку позаду м’яча під час загострення нападу.", "description": "(Повідомити про можливість повернення; не висуватися вперед разом з усіма партнерами.)", "age_from": 12, "age_to": 12, "sort_order": 165, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Створення чисельної переваги", "title": "Навчити партнерів залучати воротаря для виходу з чисельно рівного тиску.", "description": "(Показати намір повернути м’яч; воротар підтверджує доступність і бачить наступне продовження.)", "age_from": 12, "age_to": 12, "sort_order": 166, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Перехід від захисту до нападу", "title": "Навчити після заволодіння м’ячем переходити до організованого нападу за відсутності контратаки.", "description": "(Повідомити про збереження м’яча; партнери розширюють і поглиблюють доступні передачі.)", "age_from": 12, "age_to": 12, "sort_order": 167, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Вертикальні напрями розвитку атаки", "title": "Навчити команду розвивати напад через вільний фланг за перекритого центру.", "description": "(Фланговий партнер показує доступність; найближчі створюють продовження після отримання.)", "age_from": 12, "age_to": 12, "sort_order": 168, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Спосіб розіграшу стандартного положення", "title": "Навчити обирати швидкий розіграш стандарту або очікування розташування партнерів.", "description": "(Оцінити доступне продовження й дозволену процедуру; швидкість не замінює готовності адресата.)", "age_from": 12, "age_to": 12, "sort_order": 169, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "individual", "component": "Ігрове положення в захисті", "title": "Навчити обирати фронтальне, напівбокове або бокове положення для захисту.", "description": "(Враховувати загрозу удару й можливий напрямок просування суперника.)", "age_from": 12, "age_to": 12, "sort_order": 170, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Спрямування суперника з м’ячем", "title": "Навчити спрямовувати суперника в зону допомоги партнера.", "description": "(Партнер підтверджує готовність; залишений супернику напрямок має вести до узгодженої протидії.)", "age_from": 12, "age_to": 12, "sort_order": 171, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Спрямування суперника з м’ячем", "title": "Навчити своїм розташуванням спрямовувати суперника з м’ячем назад.", "description": "(Закривати просування до воріт і не відкривати небезпечну передачу під час зближення.)", "age_from": 12, "age_to": 12, "sort_order": 172, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Опіка суперника", "title": "Навчити обирати бокове положення для одночасного контролю опікуваного суперника й м’яча.", "description": "(Коригувати місце, коли суперник змінює напрямок або м’яч переходить до іншого виконавця.)", "age_from": 12, "age_to": 12, "sort_order": 173, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Боротьба за м’яч", "title": "Навчити зберігати вигідне місце в боротьбі за м’яч через дозволений контакт.", "description": "(Ураховувати положення м’яча; не замінювати боротьбу утримуванням або відштовхуванням суперника.)", "age_from": 12, "age_to": 12, "sort_order": 174, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Перекривання", "title": "Навчити під час зближення із суперником перекривати передачу за своєю спиною.", "description": "(Наближатися під кутом, який залишає адресата в тіні; ураховувати його переміщення.)", "age_from": 12, "age_to": 12, "sort_order": 175, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Відбирання м’яча", "title": "Навчити обирати відбирання на ногах із дозволеним контактом корпусом.", "description": "(Використовувати контакт для доступу до м’яча, коли суперник закриває його тілом.)", "age_from": 12, "age_to": 12, "sort_order": 176, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Перехоплення м’яча", "title": "Навчити випереджати адресата в зоні отримання передачі.", "description": "(Обирати момент після визначення напрямку м’яча; не відкривати шлях супернику завчасним виходом.)", "age_from": 12, "age_to": 12, "sort_order": 177, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Винесення м’яча", "title": "Навчити обирати адресне винесення до партнера поза небезпечною зоною.", "description": "(До контакту помітити адресата; партнер повідомляє про доступність, якщо це допомагає вибору.)", "age_from": 12, "age_to": 12, "sort_order": 178, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Винесення м’яча", "title": "Навчити обирати безадресне винесення для усунення безпосередньої загрози воротам.", "description": "(Коли надійного адресата немає, спрямувати м’яч у безпечніший бік або за межі поля.)", "age_from": 12, "age_to": 12, "sort_order": 179, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Індивідуальний пресинг", "title": "Навчити припиняти індивідуальний пресинг після втрати можливості ефективно зблизитися.", "description": "(Не переслідувати м’яч автоматично; повернутися для захисту простору й повідомити партнеру про зміну завдання.)", "age_from": 12, "age_to": 12, "sort_order": 180, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Розподіл опіки", "title": "Навчити партнерів першочергово брати під опіку суперника з безпосередньою загрозою воротам.", "description": "(Назвати загрозу й підтвердити, хто її приймає; інший партнер зберігає контроль решти доступного продовження.)", "age_from": 12, "age_to": 12, "sort_order": 181, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Переключення опіки", "title": "Навчити двох партнерів взаємно змінювати опікуваних суперників при схрещуванні або обміні місцями.", "description": "(Підтвердити обмін короткими сигналами; не припиняти опіку до готовності партнера.)", "age_from": 12, "age_to": 12, "sort_order": 182, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Підстраховка", "title": "Навчити займати позицію партнера, який виходить для захисного втручання.", "description": "(Повідомити про заміщення; після повернення партнера узгодити подальший розподіл місць.)", "age_from": 12, "age_to": 12, "sort_order": 183, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Подвоєння", "title": "Навчити двійку одночасно опікати конкретного суперника без м’яча з різних боків.", "description": "(Узгодити сторони контролю; реагувати на його відкривання, зберігаючи доступ до м’яча.)", "age_from": 12, "age_to": 12, "sort_order": 184, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Координоване переміщення захисної ланки", "title": "Навчити ланку узгоджувати діагональне зміщення під час просування м’яча флангом.", "description": "(Ближні зміщуються до м’яча, дальні захищають простір у глибині; повідомляти про суперника за спиною.)", "age_from": 12, "age_to": 12, "sort_order": 185, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Груповий пресинг", "title": "Навчити трійку обирати момент спільної спроби заволодіти м’ячем під час пресингу.", "description": "(Можливі ознаки — невдалий контакт або повільна передача; сигнал початку має збігатися з готовністю партнерів.)", "age_from": 12, "age_to": 12, "sort_order": 186, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Підключення до атаки", "title": "Навчити обирати, наскільки далеко підключатися вперед для підтримки нападу.", "description": "(Відпрацьовувати з м’ячем і без нього; враховувати зайняті місця та підтримку позаду. Кількість позиційних рівнів відповідає формату гри.)", "age_from": 13, "age_to": 13, "sort_order": 187, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Відкривання", "title": "Навчити узгоджувати відкривання за останньою лінією з моментом передачі.", "description": "(Партнер має можливість передати; адресат показує ривок і враховує «поза грою» за його застосування.)", "age_from": 13, "age_to": 13, "sort_order": 188, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Боротьба за перший м’яч", "title": "Навчити ситуативно визначати гравця першого контакту після непередбачуваного винесення партнером.", "description": "(Найкраще розташований повідомляє «Я»; інші змінюють намір, щоб не заважати йому.)", "age_from": 13, "age_to": 13, "sort_order": 189, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Комбінації", "title": "Навчити продовжувати багатоланкову комбінацію через партнера у звільненому напрямку.", "description": "(У трійці або четвірці після кожної передачі перевіряти наступне відкривання; партнер повідомляє про готовність.)", "age_from": 13, "age_to": 13, "sort_order": 190, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Створення чисельної переваги", "title": "Навчити створювати чисельну перевагу підключенням партнера з глибини.", "description": "(Показати потребу в допомозі; партнер підключається, коли може отримати передачу, а не лише збільшити скупчення.)", "age_from": 13, "age_to": 13, "sort_order": 191, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Створення чисельної переваги", "title": "Навчити створювати чисельну перевагу опусканням партнера з вищої позиції.", "description": "(Партнер із м’ячем показує потребу в підтримці; футболіст опускається в доступний проміжок.)", "age_from": 13, "age_to": 13, "sort_order": 192, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Організація атакувальної структури", "title": "Навчити команду зберігати підтримку та страхування позаду м’яча під час нападу.", "description": "(Узгодити, хто залишається при підключенні партнера; враховувати суперників, готових до контратаки.)", "age_from": 13, "age_to": 13, "sort_order": 193, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Організація атакувальної структури", "title": "Навчити команду заповнювати звільнені місця під час перебудови нападу.", "description": "(Зберігати ширину й глибину; футболіст, який змінює зону, узгоджує її зайняття партнером.)", "age_from": 13, "age_to": 13, "sort_order": 194, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Види організованої атаки", "title": "Навчити команду використовувати позиційний напад для пошуку проходу проти сформованого захисту.", "description": "(Підтримувати передачі, поки не з’явиться доступне загострення; партнери повідомляють про відкриті напрямки.)", "age_from": 13, "age_to": 13, "sort_order": 195, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Вертикальні напрями розвитку атаки", "title": "Навчити команду просувати м’яч через напівфланг.", "description": "(Адресат відкривається між центральним і фланговим захисниками; сусідні партнери узгоджують продовження.)", "age_from": 13, "age_to": 13, "sort_order": 196, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Організація завершального етапу атаки", "title": "Навчити команду розподіляти футболістів між трьома лініями завершення.", "description": "(Узгодити, хто атакує простір перед воротами, хто підтримує глибше, а хто залишається перед зоною завершення.)", "age_from": 13, "age_to": 13, "sort_order": 197, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Кутовий удар", "title": "Навчити узгоджувати подачу з кутового в зону переваги адресата над опікуном.", "description": "(Домовитися про цільову зону й сигнал; адресат показує готовність до виходу.)", "age_from": 13, "age_to": 13, "sort_order": 198, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Штрафний удар", "title": "Навчити команду обирати зону подачі зі штрафного за розташуванням адресатів і захисників.", "description": "(Виконавець і адресати узгоджують напрямок та сигнал початку ривків.)", "age_from": 13, "age_to": 13, "sort_order": 199, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Одинадцятиметровий удар", "title": "Навчити партнерів розподіляти зони наступної дії після відбитого пенальті.", "description": "(До удару підтвердити зони; вступати у гру відповідно до правил змагань.)", "age_from": 13, "age_to": 13, "sort_order": 200, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Спірний м’яч", "title": "Навчити обирати продовження нападу після отримання спірного м’яча.", "description": "(Оцінити найближчий тиск і підтримку; партнер завчасно показує доступну передачу.)", "age_from": 13, "age_to": 13, "sort_order": 201, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "individual", "component": "Боротьба за м’яч", "title": "Навчити випереджати суперника в боротьбі за м’яч у повітрі.", "description": "(Оцінювати висоту й швидкість; низькі, середні та верхові м’ячі й дозволені способи контакту добирати за підготовленістю.)", "age_from": 13, "age_to": 13, "sort_order": 202, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Відбирання м’яча", "title": "Навчити обирати відбирання у підкаті за недоступності м’яча для відбирання на ногах.", "description": "(Оцінити шанс зіграти в м’яч і наслідки невдачі; застосовувати за технічної готовності та без небезпечного контакту.)", "age_from": 13, "age_to": 13, "sort_order": 203, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Розподіл опіки", "title": "Навчити партнерів добирати опікуна супернику за його небезпечними якостями.", "description": "(Ураховувати швидкість, дальній удар або перевагу в повітрі; підтвердити розподіл до розвитку ситуації.)", "age_from": 13, "age_to": 13, "sort_order": 204, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Перехід від нападу до захисту", "title": "Навчити команду обирати контрпресинг одразу після втрати м’яча.", "description": "(Оцінити близькість і готовність партнерів та захищеність простору позаду; підтвердити спільний початок коротким сигналом.)", "age_from": 13, "age_to": 13, "sort_order": 205, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Висота захисного блоку", "title": "Навчити команду організовувати середній блок.", "description": "(Узгодити початкову висоту й відстані між лініями; ближні до м’яча повідомляють про початок активної протидії.)", "age_from": 13, "age_to": 13, "sort_order": 206, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Командний пресинг", "title": "Навчити команду одночасно починати пресинг за обраною ігровою ознакою.", "description": "(Наприклад, повільна передача або невдале приймання; підтвердити готовність ліній узгодженим сигналом.)", "age_from": 13, "age_to": 13, "sort_order": 207, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Командний пресинг", "title": "Навчити команду розподіляти ролі активного зближення, перекривання передач та опіки адресатів між лініями.", "description": "(Кожна лінія підтримує наступну; повідомляти про передачу суперника, яка потребує зміни першого пресингувальника.)", "age_from": 13, "age_to": 13, "sort_order": 208, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Система організації захисту", "title": "Навчити команду розподіляти відповідальність за простір і суперників у зонній системі.", "description": "(Партнери повідомляють про вхід суперника до сусідньої зони та підтверджують його прийняття.)", "age_from": 13, "age_to": 13, "sort_order": 209, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Штрафний удар суперника", "title": "Навчити партнерів організовувати стінку за місцем штрафного удару суперника.", "description": "(Воротар повідомляє потрібне розташування; футболіст стінки підтверджує готовність і коригує її за вказівкою.)", "age_from": 13, "age_to": 13, "sort_order": 210, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Кутовий удар суперника", "title": "Навчити партнерів узгоджувати протидію короткому розіграшу кутового.", "description": "(Один виходить до виконавця, другий контролює адресата й повернення; повідомити решті про короткий розіграш.)", "age_from": 13, "age_to": 13, "sort_order": 211, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Система організації захисту при стандартному положенні", "title": "Навчити команду розподіляти небезпечні зони під час зонного захисту стандарту.", "description": "(Підтвердити зони й відповідальність за передачу між ними; узгодити межу втручання воротаря.)", "age_from": 13, "age_to": 13, "sort_order": 212, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "group", "component": "Передача м’яча", "title": "Навчити обирати адресата в різних лініях завершення за розташуванням захисників.", "description": "(Помічати партнера перед воротами, у глибині зони або перед нею; адресати показують різні продовження.)", "age_from": 14, "age_to": 14, "sort_order": 213, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "group", "component": "Позиційна підтримка атаки", "title": "Навчити групу перебудовувати підтримку після перекривання попередніх передач.", "description": "(Один змінює місце, інші відкривають нові кути; узгоджувати переміщення, щоб не закритися одночасно.)", "age_from": 14, "age_to": 14, "sort_order": 214, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Види організованої атаки", "title": "Навчити команду швидко просувати м’яч проти сформованого захисту до його перебудови.", "description": "(Використати відкритий напрямок; партнери завчасно показують наступні передачі та ривки.)", "age_from": 14, "age_to": 14, "sort_order": 215, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Створення та використання переваги", "title": "Навчити команду звільняти фланг для гри партнера один проти одного.", "description": "(Найближчі відводять суперників; ізольований партнер показує готовність, підтримка позаду залишається доступною.)", "age_from": 14, "age_to": 14, "sort_order": 216, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Створення та використання переваги", "title": "Навчити команду змінювати бік нападу після стягування суперників до м’яча.", "description": "(Дальній партнер показує вільний простір; обирати пряму передачу або зміну через партнерів позаду.)", "age_from": 14, "age_to": 14, "sort_order": 217, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Подолання захисної структури", "title": "Навчити команду обходити захисну структуру через простір біля її краю.", "description": "(Крайній адресат показує напрямок; партнери створюють продовження всередину й підтримку позаду.)", "age_from": 14, "age_to": 14, "sort_order": 218, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Організація завершального етапу атаки", "title": "Навчити команду розподіляти ширину зони завершення відповідно до боку розвитку нападу.", "description": "(Адресати підтверджують різні коридори й не спрямовують усі ривки до м’яча.)", "age_from": 14, "age_to": 14, "sort_order": 219, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Удар від воріт", "title": "Навчити команду обирати довгу доставку від воріт за закритого короткого розіграшу.", "description": "(Підтвердити гравця першого контакту та роз