 15, "age_to": 15, "sort_order": 239, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Створення та використання переваги", "title": "Навчити команду прискорювати напад після відкриття простору між лініями суперника.", "description": "(Адресат показує доступність; найближчі партнери готують швидке наступне продовження.)", "age_from": 15, "age_to": 15, "sort_order": 240, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Створення та використання переваги", "title": "Навчити команду сповільнювати напад для залучення суперників і відкриття іншого напрямку.", "description": "(Узгоджений сигнал збереження допомагає уникати поспішної передачі; дальні партнери зберігають ширину.)", "age_from": 15, "age_to": 15, "sort_order": 241, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Подолання захисної структури", "title": "Навчити команду просувати м’яч крізь захист через відкриті проміжки.", "description": "(Адресати в різних лініях показують доступність; передавати до закриття обраного проміжку.)", "age_from": 15, "age_to": 15, "sort_order": 242, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Подолання захисної структури", "title": "Навчити команду доставляти м’яч над захисною структурою в доступний простір за нею.", "description": "(Передачу узгодити з ривком адресата й правилами «поза грою»; підготувати підбирання.)", "age_from": 15, "age_to": 15, "sort_order": 243, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Організація завершального етапу атаки", "title": "Навчити команду узгоджувати вихід адресатів у зону завершення з моментом доставки.", "description": "(Виконавець має можливість передати; адресати показують різні ривки й не займають цільові місця завчасно.)", "age_from": 15, "age_to": 15, "sort_order": 244, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Кутовий удар", "title": "Навчити команду розігрувати кутовий під удар партнеру перед штрафним майданчиком.", "description": "(Показати або узгодити відхід адресата; інші партнери створюють простір і готують підбирання.)", "age_from": 15, "age_to": 15, "sort_order": 245, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Вкидання м’яча з-за бокової лінії", "title": "Навчити команду змінювати адресата підготовленого вкидання після зміни опіки суперника.", "description": "(Мати запасне відкривання; виконавець підтверджує нового адресата поглядом, жестом або коротким сигналом.)", "age_from": 15, "age_to": 15, "sort_order": 246, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Організація футболістів у нападі при стандартному положенні", "title": "Навчити команду розподіляти створення простору, підтримку й підбирання під час атакувального стандарту.", "description": "(До виконання підтвердити завдання й сигнал; після першої дії реагувати на фактичне продовження.)", "age_from": 15, "age_to": 15, "sort_order": 247, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "individual", "component": "Спрямування суперника з м’ячем", "title": "Навчити спрямовувати суперника до центру за узгодженої допомоги партнерів.", "description": "(Партнери підтверджують готовність закрити виходи; відмовитися від цього напрямку, якщо допомоги немає.)", "age_from": 15, "age_to": 15, "sort_order": 248, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Боротьба за м’яч", "title": "Навчити в боротьбі спрямовувати вільний м’яч у вигідний простір або за межі поля.", "description": "(Обирати за загрозою воротам і готовністю партнерів продовжити; уникати скидки вільному супернику.)", "age_from": 15, "age_to": 15, "sort_order": 249, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Координоване переміщення захисної ланки", "title": "Навчити ланку обирати збереження, зменшення або збільшення відстаней між партнерами.", "description": "(Ураховувати простір, доступний супернику; сусідні футболісти узгоджують корекцію коротким повідомленням.)", "age_from": 15, "age_to": 15, "sort_order": 250, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Перехід від нападу до захисту", "title": "Навчити команду переходити від контрпресингу до відновлення захисної організації.", "description": "(Ознака — суперник вивів м’яч із зони спільної протидії; узгоджений сигнал змінює завдання найближчих і дальніх партнерів.)", "age_from": 15, "age_to": 15, "sort_order": 251, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Організація захисної структури", "title": "Навчити команду перебудовувати захист після переведення нападу суперника на іншу ділянку поля.", "description": "(Лінії зміщуються взаємопов’язано; повідомляти про нових адресатів, особливо на дальньому боці.)", "age_from": 15, "age_to": 15, "sort_order": 252, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Висота захисного блоку", "title": "Навчити команду організовувати низький блок для захисту воріт і простору поблизу них.", "description": "(Узгодити захист центру, передач перед воротами й відскоку; воротар повідомляє про небезпечні переміщення.)", "age_from": 15, "age_to": 15, "sort_order": 253, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Командний пресинг", "title": "Навчити команду обирати зону пресингу за доступними супернику шляхами розвитку нападу.", "description": "(Узгодити, де починається спільне зближення і які виходи перекривають наступні лінії.)", "age_from": 15, "age_to": 15, "sort_order": 254, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Командний пресинг", "title": "Навчити команду припиняти пресинг після подолання суперником узгодженого тиску.", "description": "(За неможливості підтримати наступне зближення підтвердити відступ; лінії відновлюють взаємні відстані.)", "age_from": 15, "age_to": 15, "sort_order": 255, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Система організації захисту", "title": "Навчити команду поєднувати зонні й персональні завдання в комбінованому захисті.", "description": "(Погодити, кого опікують персонально, а хто захищає простір; повідомляти про перехід відповідальності.)", "age_from": 15, "age_to": 15, "sort_order": 256, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Кутовий удар суперника", "title": "Навчити команду узгоджено виходити із зони воріт після винесення кутового.", "description": "(Оцінити, хто може зіграти наступним; сигнал виходу не скасовує контролю суперників і передачі за спину.)", "age_from": 15, "age_to": 15, "sort_order": 257, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Система організації захисту при стандартному положенні", "title": "Навчити команду поєднувати зонні й персональні завдання під час захисту стандарту.", "description": "(Кожен підтверджує свою зону або суперника; погодити відповідальність на межі зон і з воротарем.)", "age_from": 15, "age_to": 15, "sort_order": 258, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Організація футболістів у захисті при стандартному положенні", "title": "Навчити визначати партнера для протидії можливому швидкому розіграшу суперника.", "description": "(Партнер повідомляє про розіграш; діяти з дозволеного місця без незаконного затримування поновлення.)", "age_from": 15, "age_to": 15, "sort_order": 259, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Організація футболістів у захисті при стандартному положенні", "title": "Навчити команду залишати доступного адресата для переходу в напад після захисту стандарту.", "description": "(Адресат показує готовність; команда узгоджує його місце, зберігаючи достатній захист небезпечних зон.)", "age_from": 15, "age_to": 15, "sort_order": 260, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Вільний удар суперника", "title": "Навчити команду узгоджувати вихід до м’яча після першої передачі з вільного удару суперника.", "description": "(Визначити першого, хто зближується, та партнерів перекривання; момент виходу відповідає процедурі поновлення.)", "age_from": 15, "age_to": 15, "sort_order": 261, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Спірний м’яч суперника", "title": "Навчити команду обмежувати перше продовження суперника після отримання спірного м’яча.", "description": "(До поновлення узгодити напрямки протидії; дотримуватися дозволеної дистанції й процедури.)", "age_from": 15, "age_to": 15, "sort_order": 262, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Створення та використання переваги", "title": "Навчити команду перевантажувати обрану зону, зберігаючи продовження на протилежному боці.", "description": "(Дальній партнер показує доступність; при залученні додаткового гравця узгодити підтримку позаду.)", "age_from": 16, "age_to": 16, "sort_order": 263, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Створення та використання переваги", "title": "Навчити команду просувати м’яч через цільового гравця під тиском.", "description": "(Узгодити доставку та наступних адресатів; цільовий гравець повідомляє про готовність до приймання або скидки.)", "age_from": 16, "age_to": 16, "sort_order": 264, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Створення та використання переваги", "title": "Навчити команду використовувати рух цільового гравця для звільнення інших адресатів.", "description": "(Узгодити, хто використовує звільнену зону; виконавець доставки перевіряє обидва продовження.)", "age_from": 16, "age_to": 16, "sort_order": 265, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Організація завершального етапу атаки", "title": "Навчити футболістів різних ліній завершення змінювати зайняті зони для звільнення адресата.", "description": "(Підтвердити обмін місцями; зберегти різну глибину й готовність до фактичного моменту передачі.)", "age_from": 16, "age_to": 16, "sort_order": 266, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "attack", "level": "team", "component": "Початковий удар", "title": "Навчити команду спрямовано просувати м’яч після початкового удару в обрану зону.", "description": "(До поновлення узгодити першу передачу, відкривання адресата й підтримку другого продовження.)", "age_from": 16, "age_to": 16, "sort_order": 267, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Штрафний удар", "title": "Навчити виконавця штрафного змінювати розіграш після перекривання основного адресата.", "description": "(Запасний адресат показує доступність; зміна підтверджується узгодженим сигналом до виконання.)", "age_from": 16, "age_to": 16, "sort_order": 268, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Організація футболістів у нападі при стандартному положенні", "title": "Навчити команду визначати склад страхування від контратаки під час атакувального стандарту.", "description": "(Ураховувати залишених попереду суперників; партнери підтверджують, хто контролює м’яч, адресатів і простір позаду.)", "age_from": 16, "age_to": 16, "sort_order": 269, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Організація футболістів у нападі при стандартному положенні", "title": "Навчити партнерів перерозподіляти функції перед стандартом за недоступності основного виконавця або адресата.", "description": "(Заміни підтверджують усі залучені; новий виконавець перевіряє готовність партнерів.)", "age_from": 16, "age_to": 16, "sort_order": 270, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "individual", "component": "Блокування м’яча", "title": "Навчити блокувати винесення для перешкоджання виходу суперника з небезпечної для нього зони.", "description": "(Зблизитися до можливого контакту з м’ячем; після блокування реагувати на його новий напрямок.)", "age_from": 16, "age_to": 16, "sort_order": 271, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "group", "component": "Створення офсайдної пастки", "title": "Навчити одного або кількох футболістів останньої лінії виходити вперед для створення офсайдної пастки.", "description": "(За застосування правила контролювати момент передачі й найглибшого партнера; узгодити своєчасний вихід усіх, хто визначає лінію.)", "age_from": 16, "age_to": 16, "sort_order": 272, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Організація захисної структури", "title": "Навчити команду змінювати кількість захисних ліній відповідно до перебудови нападу суперника.", "description": "(Узгодити нові місця й відповідальність до розриву між лініями; визначений партнер підтверджує перебудову.)", "age_from": 16, "age_to": 16, "sort_order": 273, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Організація захисної структури", "title": "Навчити команду перерозподіляти футболістів усередині захисної лінії проти перевантаження одного боку.", "description": "(Найближчі уточнюють опіку, дальні захищають звільнений простір; підтвердити зміну відповідальності.)", "age_from": 16, "age_to": 16, "sort_order": 274, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Висота захисного блоку", "title": "Навчити команду змінювати висоту блоку після віддалення м’яча від власних воріт.", "description": "(Оцінювати контроль м’яча суперником і тиск на нього; сигнал підняття підтримують усі лінії.)", "age_from": 16, "age_to": 16, "sort_order": 275, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Командний пресинг", "title": "Навчити команду продовжувати пресинг після поперечної передачі суперника зі зміною першого пресингувальника.", "description": "(Новий гравець підтверджує вихід; попередній перекриває повернення, інші лінії підтримують зміщення.)", "age_from": 16, "age_to": 16, "sort_order": 276, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Командний пресинг", "title": "Навчити команду змінювати розподіл пресингових ролей після залучення суперником додаткового гравця до розіграшу.", "description": "(Розпізнати вільного адресата або воротаря; узгодити нові виходи без розриву між лініями.)", "age_from": 16, "age_to": 16, "sort_order": 277, "audience": "field", "goalkeeper_stage": "", "context": "play"}, {"phase": "defence", "level": "team", "component": "Штрафний удар суперника", "title": "Навчити футболістів стінки обирати наступне розташування після розіграшу штрафного через передачу.", "description": "(Один реагує на м’яч, інші захищають продовження; воротар повідомляє про нову загрозу.)", "age_from": 16, "age_to": 16, "sort_order": 278, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Кутовий удар суперника", "title": "Навчити команду перерозподіляти зони захисту після зміни способу доставки з кутового.", "description": "(Повідомити про короткий розіграш або новий бік подачі; підтвердити нових адресатів і відповідальність воротаря.)", "age_from": 16, "age_to": 16, "sort_order": 279, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Удар від воріт суперника", "title": "Навчити команду розподіляти захист зон довгої доставки від воріт суперника.", "description": "(Узгодити першого учасника боротьби, підстраховку та підбирання; за польотом м’яча уточнити відповідальність голосом.)", "age_from": 16, "age_to": 16, "sort_order": 280, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Організація футболістів у захисті при стандартному положенні", "title": "Навчити партнерів розподіляти захист небезпечного простору й перше втручання під час подачі зі стандарту.", "description": "(Визначити, хто атакує м’яч, а хто зберігає контроль простору; голосовий сигнал уточнює вихід до подачі.)", "age_from": 16, "age_to": 16, "sort_order": 281, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Організація футболістів у захисті при стандартному положенні", "title": "Навчити команду узгоджувати відповідальність воротаря й польових футболістів за зону подачі.", "description": "(Воротар завчасно повідомляє про вихід або залишення в позиції; партнери відповідно змінюють свої завдання.)", "age_from": 16, "age_to": 16, "sort_order": 282, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Організація футболістів у захисті при стандартному положенні", "title": "Навчити команду перерозподіляти захисні функції перед стандартом за відсутності основного виконавця завдання.", "description": "(Новий опікун або футболіст стінки підтверджує роль; сусідні партнери перевіряють, чи не залишилася вільна відповідальність.)", "age_from": 16, "age_to": 16, "sort_order": 283, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Організація футболістів у захисті при стандартному положенні", "title": "Навчити команду коригувати розподіл захисних завдань після несподіваного швидкого розіграшу.", "description": "(Найближчий протидіє м’ячу; партнери повідомляють, яких адресатів і напрямки приймають під контроль.)", "age_from": 16, "age_to": 16, "sort_order": 284, "audience": "field", "goalkeeper_stage": "", "context": "standard"}, {"phase": "attack", "level": "individual", "component": "Вибір позиції для підтримки розіграшу", "title": "Навчити воротаря займати видиме партнеру місце для передачі назад.", "description": "(Не ховатися за суперником; показати готовність поглядом або коротким звертанням.)", "age_from": 6, "age_to": 8, "sort_order": 285, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Вибір позиції для підтримки розіграшу", "title": "Навчити воротаря зміщуватися вбік для відкриття перекритої передачі до нього.", "description": "(Партнер має побачити новий напрямок; за потреби воротар привертає його увагу.)", "age_from": 6, "age_to": 8, "sort_order": 286, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Збереження м’яча під власним контролем", "title": "Навчити воротаря зберігати м’яч після оволодіння, коли готового продовження немає.", "description": "(Перевіряти появу доступного партнера; дотримуватися дозволеного часу контролю руками.)", "age_from": 6, "age_to": 8, "sort_order": 287, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Збереження м’яча під власним контролем", "title": "Навчити воротаря закривати м’яч тілом під час наближення суперника.", "description": "(Йдеться про м’яч біля ніг; зберігати можливість віддати його доступному партнеру.)", "age_from": 6, "age_to": 8, "sort_order": 288, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Просування з м’ячем", "title": "Навчити воротаря просуватися з м’ячем у вільний простір для полегшення передачі.", "description": "(Зупиняти просування перед зближенням суперника; помічати партнера для продовження.)", "age_from": 6, "age_to": 8, "sort_order": 289, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "attack", "level": "group", "component": "Взаємне розташування воротаря і партнерів", "title": "Навчити воротаря й партнера відкриватися один для одного.", "description": "(Показувати вільний напрямок поглядом або жестом; уникати розташування за суперником.)", "age_from": 6, "age_to": 8, "sort_order": 290, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "attack", "level": "group", "component": "Взаємне розташування воротаря і партнерів", "title": "Навчити воротаря й партнера обирати відстань для надійної передачі.", "description": "(Наближатися, коли передача недосяжна; поглядом або жестом показувати зручне місце, не підбігаючи впритул.)", "age_from": 6, "age_to": 8, "sort_order": 291, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "attack", "level": "group", "component": "Взаємодія через передачі м’яча", "title": "Навчити воротаря передавати м’яч після підтвердження готовності партнера.", "description": "(Достатньо зрозумілого погляду, жесту або короткого звертання; не передавати партнеру, який не бачить м’яча.)", "age_from": 6, "age_to": 8, "sort_order": 292, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "attack", "level": "group", "component": "Взаємодія через передачі м’яча", "title": "Навчити воротаря обирати передачу в ноги партнеру або йому на хід.", "description": "(Враховувати рух партнера; він показує, де очікує м’яч.)", "age_from": 6, "age_to": 8, "sort_order": 293, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "attack", "level": "team", "component": "Участь воротаря в переході від захисту до нападу", "title": "Навчити воротаря помічати можливість швидкого початку атаки після оволодіння м’ячем.", "description": "(Партнер попереду показує відкритий шлях; починати без зайвого очікування за доступної передачі.)", "age_from": 6, "age_to": 8, "sort_order": 294, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "attack", "level": "team", "component": "Виконання воротарем удару від воріт, штрафного або вільного удару", "title": "Навчити воротаря обирати вільного партнера для удару від воріт.", "description": "(Перевірити його готовність і відсутність суперника на шляху; уточнити намір поглядом або голосом.)", "age_from": 6, "age_to": 8, "sort_order": 295, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "standard"}, {"phase": "defence", "level": "individual", "component": "Вибір позиції", "title": "Навчити воротаря обирати місце між м’ячем і воротами для протидії удару.", "description": "(Спочатку впізнавати власні ворота й місце м’яча; не вводити кілька позиційних вимог одночасно.)", "age_from": 6, "age_to": 8, "sort_order": 296, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Вибір позиції", "title": "Навчити воротаря змінювати позицію після переміщення м’яча перед воротами.", "description": "(Після кожної передачі знову бачити м’яч і захищати напрямок до воріт.)", "age_from": 6, "age_to": 8, "sort_order": 297, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Вихід на м’яч або суперника", "title": "Навчити воротаря обирати вихід на вільний м’яч або залишення в позиції.", "description": "(Виходити, якщо може зіграти раніше за суперника; завчасно повідомити партнеру про свій вихід.)", "age_from": 6, "age_to": 8, "sort_order": 298, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Протидія удару", "title": "Навчити воротаря обирати ловіння для збереження м’яча після удару.", "description": "(Застосовувати, коли напрямок і швидкість м’яча дозволяють надійно його зафіксувати.)", "age_from": 6, "age_to": 8, "sort_order": 299, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Протидія удару", "title": "Навчити воротаря обирати затримання м’яча з наступним оволодінням.", "description": "(Коли негайна фіксація недоступна, залишити м’яч у досяжному просторі й продовжити дію.)", "age_from": 6, "age_to": 8, "sort_order": 300, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Продовження захисту після першого втручання", "title": "Навчити воротаря підбирати доступний м’яч після першого втручання.", "description": "(Перевіряти, чи можна встигнути раніше за суперника; повідомляти партнеру про наступний вихід.)", "age_from": 6, "age_to": 8, "sort_order": 301, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "defence", "level": "group", "component": "Узгодження розташування воротаря і захисників", "title": "Навчити воротаря й захисника узгоджувати місця для захисту воріт і простору між ними.", "description": "(Бачити один одного; попереджати про суперника, якого партнер може не помітити.)", "age_from": 6, "age_to": 8, "sort_order": 302, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "play"}, {"phase": "defence", "level": "team", "component": "Кутовий удар суперника", "title": "Навчити воротаря обирати початкове місце під час кутового суперника.", "description": "(Бачити м’яч і простір перед воротами; починати з простого розташування без складних переміщень партнерів.)", "age_from": 6, "age_to": 8, "sort_order": 303, "audience": "goalkeeper", "goalkeeper_stage": "A", "context": "standard"}, {"phase": "attack", "level": "individual", "component": "Вибір позиції для підтримки розіграшу", "title": "Навчити воротаря обирати глибину підтримки відповідно до місця володіння команди.", "description": "(Помічати можливість зворотної передачі та небезпеку її перехоплення; повідомляти про свою доступність.)", "age_from": 9, "age_to": 12, "sort_order": 304, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Збереження м’яча під власним контролем", "title": "Навчити воротаря утриманням м’яча ногами залучати суперника для відкриття передачі партнеру.", "description": "(Партнер показує вільний напрямок; передавати до втрати можливості надійно зіграти.)", "age_from": 9, "age_to": 12, "sort_order": 305, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "attack", "level": "individual", "component": "Просування з м’ячем", "title": "Навчити воротаря обирати момент припинення просування з м’ячем.", "description": "(Враховувати наближення суперника, доступного партнера й захищеність воріт; повідомити партнеру про намір передати.)", "age_from": 9, "age_to": 12, "sort_order": 306, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "attack", "level": "group", "component": "Взаємне розташування воротаря і партнерів", "title": "Навчити воротаря й двох партнерів відкривати різні напрямки розіграшу.", "description": "(Не ставати на одній лінії; за зміни тиску повідомляти, який партнер доступний.)", "age_from": 9, "age_to": 12, "sort_order": 307, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "attack", "level": "group", "component": "Взаємодія через передачі м’яча", "title": "Навчити воротаря обирати напрямок і дистанцію передачі для подолання лінії тиску.", "description": "(Розрізняти доступного партнера перед лінією та за нею; адресат показує готовність до обраної доставки.)", "age_from": 9, "age_to": 12, "sort_order": 308, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "attack", "level": "group", "component": "Взаємодія через передачі м’яча", "title": "Навчити воротаря узгоджувати передачу вперед із ривком віддаленого партнера.", "description": "(Підтвердити намір до виконання; передавати, поки адресат може випередити суперника.)", "age_from": 9, "age_to": 12, "sort_order": 309, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "attack", "level": "group", "component": "Створення та використання чисельної переваги за участю воротаря", "title": "Навчити воротаря й двох захисників використовувати вільного партнера в ситуації 3×2.", "description": "(Залучити суперника до м’яча; вільний партнер показує готовність, а третій зберігає наступне продовження.)", "age_from": 9, "age_to": 12, "sort_order": 310, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "attack", "level": "group", "component": "Створення та використання чисельної переваги за участю воротаря", "title": "Навчити воротаря підключатися як додатковий партнер за чисельної рівності польових футболістів біля м’яча.", "description": "(Партнери запрошують підтримку або показують передачу назад; воротар відкриває новий напрямок взаємодії.)", "age_from": 9, "age_to": 12, "sort_order": 311, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "attack", "level": "team", "component": "Участь воротаря в переході від захисту до нападу", "title": "Навчити воротаря обирати організований початок нападу за закритого швидкого продовження.", "description": "(Коротко повідомити про збереження м’яча; партнери займають доступні місця для побудови.)", "age_from": 9, "age_to": 12, "sort_order": 312, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "attack", "level": "team", "component": "Виконання воротарем удару від воріт, штрафного або вільного удару", "title": "Навчити воротаря обирати швидкий розіграш стандарту або очікування готовності партнерів.", "description": "(Адресат підтверджує готовність; враховувати процедуру удару від воріт, штрафного чи вільного удару.)", "age_from": 9, "age_to": 12, "sort_order": 313, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Участь воротаря у стандартних положеннях, які виконують партнери", "title": "Навчити воротаря підтримувати розіграш удару від воріт, який виконує партнер.", "description": "(Показати доступність для повернення; узгодити, хто виконує першу дію й хто продовжує розіграш.)", "age_from": 9, "age_to": 12, "sort_order": 314, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "standard"}, {"phase": "defence", "level": "individual", "component": "Вибір позиції", "title": "Навчити воротаря обирати позицію для гри в небезпечному просторі.", "description": "(Наприклад, за лінією захисту або перед воротами на можливій передачі поперек; повідомляти про загрозу партнерам.)", "age_from": 9, "age_to": 12, "sort_order": 315, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Вибір позиції", "title": "Навчити воротаря змінювати позицію між захистом простору й безпосереднім захистом воріт.", "description": "(Коли суперник отримує можливість удару, оцінити потребу зменшити відкритий простір воріт.)", "age_from": 9, "age_to": 12, "sort_order": 316, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Вихід на м’яч або суперника", "title": "Навчити воротаря обирати вихід на передачу за захисну лінію.", "description": "(Порівняти можливість досягти м’яча із швидкістю суперника; завчасно повідомити захисникам про свій вихід.)", "age_from": 9, "age_to": 12, "sort_order": 317, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Вихід на м’яч або суперника", "title": "Навчити воротаря обирати перехоплення низової передачі перед воротами або збереження позиції.", "description": "(Оцінити шлях м’яча й доступність контакту; при виході повідомити партнерам про своє втручання.)", "age_from": 9, "age_to": 12, "sort_order": 318, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Вихід на м’яч або суперника", "title": "Навчити воротаря обирати вихід на подачу або залишення для захисту воріт.", "description": "(Оцінювати траєкторію, гравців на шляху та свою досяжність; повідомити про рішення. Відпрацьовувати також на кутових.)", "age_from": 9, "age_to": 12, "sort_order": 319, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Вихід на м’яч або суперника", "title": "Навчити воротаря обирати момент початку зближення в ситуації один проти одного.", "description": "(Враховувати контроль м’яча суперником і захисника, який повертається; повідомити про вихід, якщо партнер ще може втрутитися.)", "age_from": 9, "age_to": 12, "sort_order": 320, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Протидія удару", "title": "Навчити воротаря обирати відбивання в менш небезпечний простір за неможливості оволодіння.", "description": "(До удару помічати суперників, готових до добивання; після відбивання перевірити нову загрозу.)", "age_from": 9, "age_to": 12, "sort_order": 321, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Протидія удару", "title": "Навчити воротаря обирати переведення м’яча за межі поля для усунення загрози.", "description": "(Коли збереження м’яча на полі залишає небезпечне продовження, обирати доступний вихід за межі поля.)", "age_from": 9, "age_to": 12, "sort_order": 322, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Протидія удару", "title": "Навчити воротаря обирати блокування удару на близькій дистанції.", "description": "(Застосовувати за браку часу для іншої надійної протидії; рішення відпрацьовувати з можливістю удару й продовження ведення.)", "age_from": 9, "age_to": 12, "sort_order": 323, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "individual", "component": "Продовження захисту після першого втручання", "title": "Навчити воротаря відновлювати позицію після першого втручання.", "description": "(Орієнтуватися на нове положення м’яча; повідомляти захиснику про суперника, який готує продовження.)", "age_from": 9, "age_to": 12, "sort_order": 324, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "group", "component": "Узгодження розташування воротаря і захисників", "title": "Навчити воротаря узгоджувати глибину позиції з підняттям або відступом захисників.", "description": "(Зберігати можливість зіграти за їхньою спиною; підтверджувати зміну висоти й попереджати про ривок суперника.)", "age_from": 9, "age_to": 12, "sort_order": 325, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "group", "component": "Розподіл відповідальності за безпосереднє втручання", "title": "Навчити воротаря й захисника узгоджувати вихід воротаря та підстраховку партнером.", "description": "(Воротар завчасно повідомляє «Я» або «Виходжу»; партнер звільняє шлях і захищає залишений простір.)", "age_from": 9, "age_to": 12, "sort_order": 326, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "group", "component": "Розподіл відповідальності за безпосереднє втручання", "title": "Навчити воротаря й захисника узгоджувати втручання захисника та наступну дію воротаря.", "description": "(Захисник підтверджує втручання; воротар зберігає позицію для протидії удару, обіграшу або передачі.)", "age_from": 9, "age_to": 12, "sort_order": 327, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "play"}, {"phase": "defence", "level": "team", "component": "Кутовий удар суперника", "title": "Навчити воротаря узгоджувати з партнерами зони відповідальності під час кутового суперника.", "description": "(До подачі підтвердити опіку, захист простору й зону можливого виходу воротаря; уточнювати зміни короткими сигналами.)", "age_from": 9, "age_to": 12, "sort_order": 328, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Штрафний та вільний удари суперника", "title": "Навчити воротаря обирати захист зі стінкою або без неї під час штрафного чи вільного удару.", "description": "(Оцінювати місце м’яча й характер загрози; повідомити партнерам рішення та їхні завдання.)", "age_from": 9, "age_to": 12, "sort_order": 329, "audience": "goalkeeper", "goalkeeper_stage": "B", "context": "standard"}, {"phase": "attack", "level": "team", "component": "Участь воротаря в організованому нападі", "title": "Навчити воротаря займати узгоджене з лініями команди місце в початковій побудові нападу.", "description": "(Підлаштовувати підтримку під переміщення першої лінії; партнери підтверджують, який напрямок розіграшу відкритий.)", "age_from": 13, "age_to": 16, "sort_order": 330, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "attack", "level": "team", "component": "Участь воротаря в організованому нападі", "title": "Навчити воротаря підтримувати повернення м’яча для збереження командного володіння під тиском.", "description": "(Завчасно повідомляти про доступність; інші лінії готують наступні варіанти після повернення.)", "age_from": 13, "age_to": 16, "sort_order": 331, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "attack", "level": "team", "component": "Участь воротаря в організованому нападі", "title": "Навчити воротаря обирати передачу за першу лінію пресингу за розташуванням команди.", "description": "(Узгодити адресата й підтримку після отримання; оцінювати не лише першу передачу, а й доступне наступне продовження.)", "age_from": 13, "age_to": 16, "sort_order": 332, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "attack", "level": "team", "component": "Участь воротаря в організованому нападі", "title": "Навчити воротаря змінювати бік розвитку нападу відповідно до командного задуму.", "description": "(Дальній партнер показує готовність; зміна підтримується переміщеннями сусідніх ліній, а не лише діагональною передачею.)", "age_from": 13, "age_to": 16, "sort_order": 333, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "attack", "level": "team", "component": "Виконання воротарем удару від воріт, штрафного або вільного удару", "title": "Навчити воротаря обирати просування після штрафного або вільного удару за характером пресингу суперника.", "description": 