, "context": "play"}, {"phase": "defence", "level": "individual", "component": "Продовження захисту після першого втручання", "title": "Навчити воротаря повторно протидіяти супернику з м’ячем після незавершеного першого втручання.", "description": "(Швидко визначати нову можливість удару або обіграшу; повідомляти партнеру, якщо той може першим допомогти.)", "age_from": 13, "age_to": 16, "sort_order": 339, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "defence", "level": "group", "component": "Узгодження розташування воротаря і захисників", "title": "Навчити воротаря узгоджувати бокове зміщення із захисниками для захисту простору за краєм лінії.", "description": "(Повідомляти про фланговий ривок або передачу; партнери уточнюють, хто супроводжує суперника, а хто грає в м’яч.)", "age_from": 13, "age_to": 16, "sort_order": 340, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "defence", "level": "group", "component": "Розподіл відповідальності за безпосереднє втручання", "title": "Навчити воротаря й захисника обирати позиційну протидію без негайного виходу до м’яча.", "description": "(Коли першим до м’яча встигає суперник, узгодити захист напрямків замість одночасного невдалого зближення.)", "age_from": 13, "age_to": 16, "sort_order": 341, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "defence", "level": "team", "component": "Участь воротаря в організованому захисті", "title": "Навчити воротаря захищати простір за останньою лінією відповідно до командного блоку.", "description": "(Пов’язувати позицію з висотою ліній і тиском на м’яч; повідомляти про загрозу передачі за спину.)", "age_from": 13, "age_to": 16, "sort_order": 342, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "defence", "level": "team", "component": "Участь воротаря в організованому захисті", "title": "Навчити воротаря обирати місце для захисту воріт і близького простору під час низького блоку.", "description": "(Враховувати перекритий огляд і передачі перед воротами; повідомляти захисникам про небезпечних адресатів.)", "age_from": 13, "age_to": 16, "sort_order": 343, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "defence", "level": "team", "component": "Участь воротаря в переході від нападу до захисту", "title": "Навчити воротаря змінювати позицію після втрати м’яча під час контрпресингу команди.", "description": "(Оцінити можливість партнерів утримати тиск; попереджати про передачу за спину й бути готовим змінити висоту.)", "age_from": 13, "age_to": 16, "sort_order": 344, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "defence", "level": "team", "component": "Участь воротаря в переході від нападу до захисту", "title": "Навчити воротаря узгоджувати свою позицію з поверненням команди до захисної організації.", "description": "(Повідомляти про суперників попереду та напрямки загрози; з наближенням удару забезпечувати готовність до захисту воріт.)", "age_from": 13, "age_to": 16, "sort_order": 345, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "play"}, {"phase": "defence", "level": "team", "component": "Штрафний та вільний удари суперника", "title": "Навчити воротаря узгоджувати свою позицію зі стінкою, м’ячем і воротами.", "description": "(Дати чітку вказівку щодо краю стінки; отримати підтвердження й повторно перевірити огляд перед виконанням.)", "age_from": 13, "age_to": 16, "sort_order": 346, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Штрафний та вільний удари суперника", "title": "Навчити воротаря обирати готовність до прямого удару або виходу на передачу зі стандарту.", "description": "(Помічати розташування виконавця й адресатів; про вихід повідомляти партнерам без втрати готовності до зміни задуму.)", "age_from": 13, "age_to": 16, "sort_order": 347, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Одинадцятиметровий удар суперника", "title": "Навчити воротаря обирати завчасне визначення напрямку протидії пенальті.", "description": "(Спиратися на підготовлене оцінювання виконавця; узгодити з партнерами наступну дію після можливого відбиття.)", "age_from": 13, "age_to": 16, "sort_order": 348, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "standard"}, {"phase": "defence", "level": "team", "component": "Одинадцятиметровий удар суперника", "title": "Навчити воротаря відкладати вибір напрямку протидії пенальті до читання дій виконавця.", "description": "(Стежити за розбігом і контактом із м’ячем; не порушувати вимоги до положення воротаря під час удару.)", "age_from": 13, "age_to": 16, "sort_order": 349, "audience": "goalkeeper", "goalkeeper_stage": "C", "context": "standard"}]$curriculum$::jsonb) as x(phase text,level text,component text,title text,description text,age_from smallint,age_to smallint,sort_order integer,audience text,goalkeeper_stage text,context text);
